SELECT exec.*,com.name AS companyName
FROM dsp_input_exec AS exec
LEFT JOIN dsp_company AS com ON exec.company_id = com.id


        AND exec.company_id = #{reqVO.companyId}


        AND exec.input_time BETWEEN #{reqVO.inputTime[0]} AND #{reqVO.inputTime[1]}


        AND exec.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}


ORDER BY exec.id DESC

